# Surah Al-Kahf (chapter 18) — part 4: ayat 31-40 (IDs 2171-2180)
SURAH = 18

ENTRIES = {
2171: (
"وہ لوگ جن کے لیے عدن کی جنتیں ہیں جن کے نیچے نہریں بہتی ہیں — وہ وہاں سونے کے کنگن پہنائے جائیں گے — اور ریشم کے سبز کپڑے پہنیں گے — وہ وہاں تختوں پر متقی ٹیک لگائے بیٹھیں گے — کتنا اچھا بدلہ ہے اور کتنی اچھی آرام گاہ ہے",
"""۱۔ مؤمنوں کا ٹھکانہ — جناتِ عدن؛ سونے کے کنگن؛ ریشم کا لباس؛ بہترین آرام گاہ۔
۲۔ ’’أُولَٰئِكَ لَهُمْ جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِّن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَّكِئِينَ فِيهَا عَلَى الْأَرَائِكِ نِعْمَ الثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا‘‘ — وہ لوگ جن کے لیے عدن کی جنتیں ہیں جن کے نیچے نہریں بہتی ہیں — وہ وہاں سونے کے کنگن پہنائے جائیں گے — اور ریشم کے سبز کپڑے پہنیں گے — وہ وہاں تختوں پر متقی ٹیک لگائے بیٹھیں گے — کتنا اچھا بدلہ ہے اور کتنی اچھی آرام گاہ ہے — یعنی ان کے لیے عدن کی جنتیں ہیں جن کے نیچے نہریں بہتی ہیں — وہ وہاں سونے کے کنگنوں سے زیور پہنائے جائیں گے اور ریشم کے سبز کپڑے ہوں گے — وہ وہاں تختوں پر ٹیک لگائے بیٹھیں گے — کتنا اچھا ان کا بدلہ اور کتنی اچھی ان کی آرام گاہ ہے۔
۳۔ عملی سبق: جنت کی لذتیں دائمی ہیں؛ نیک عمل کرو؛ اللہ سے بس جنت مانگو۔"""
),
2172: (
"اور ان کے لیے دو آدمیوں کی مثال بیان کرو — ہم نے ان میں سے ایک کو دو باغ دیئے انگوروں کے — اور انہیں کھجوروں کے درخت سے گھیرا — اور ان دونوں کے درمیان کھیتی کی",
"""۱۔ دنیا کی عارضی دولت کی مثال — ایک شخص کے دو باغ؛ اللہ کے نشان کا عبرت۔
۲۔ ’’وَاضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَابٍ وَحَفَفْنَاهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا‘‘ — اور ان کے لیے دو آدمیوں کی مثال بیان کرو — ہم نے ان میں سے ایک کو دو باغ دیئے انگوروں کے — اور انہیں کھجوروں کے درخت سے گھیرا — اور ان دونوں کے درمیان کھیتی کی — یعنی آپ ان کے لیے دو آدمیوں کی مثال بیان کریں — ہم نے ان میں سے ایک کو انگوروں کے دو باغ دیئے اور انہیں کھجوروں سے گھیرا اور ان دونوں کے درمیان کھیتی کی۔
۳۔ عملی سبق: دنیا کی دولت اللہ کی عطا ہے؛ اس پر فخر نہ کرو؛ اللہ کا شکر کرو۔"""
),
2173: (
"دونوں باغوں نے اپنا پھل پوری طرح دیا — اور ان سے کچھ بھی کم نہ کیا — اور ہم نے ان دونوں کے درمیان ایک نہر جاری کی",
"""۱۔ اللہ نے باغ کو بارآور کیا؛ دونوں باغوں نے کھلا پھل دیا؛ درمیان میں نہر۔
۲۔ ’’كِلْتَا الْجَنَّتَيْنِ آتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْئًا وَفَجَّرْنَا خِلَالَهُمَا نَهَرًا‘‘ — دونوں باغوں نے اپنا پھل پوری طرح دیا — اور ان سے کچھ بھی کم نہ کیا — اور ہم نے ان دونوں کے درمیان ایک نہر جاری کی — یعنی دونوں باغوں نے اپنا پھل پوری طرح دے دیا اور اس میں سے کچھ نہ کم کیا اور ہم نے ان دونوں کے درمیان ایک نہر جاری کی۔
۳۔ عملی سبق: اللہ کی نعمتوں پر شکر کرو؛ فضل پر بھروسہ رکھو؛ اللہ دیتا ہے۔"""
),
2174: (
"اور اس کے لیے پھل تھے — پس وہ اپنے ساتھی سے بولا جبکہ وہ اس سے گفتگو کر رہا تھا کہ میں تم سے مال میں زیادہ ہوں اور عزت کے اعتبار سے بھی",
"""۱۔ مالدار آدمی کی تکبر — مال اور عزت دونوں میں خود کو افضل سمجھتا ہے۔
۲۔ ’’وَكَانَ لَهُ ثَمَرٌ فَقَالَ لِصَاحِبِهِ وَهُوَ يُحَاوِرُهُ أَنَا أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا‘‘ — اور اس کے لیے پھل تھے — پس وہ اپنے ساتھی سے بولا جبکہ وہ اس سے گفتگو کر رہا تھا کہ میں تم سے مال میں زیادہ ہوں اور عزت کے اعتبار سے بھی — یعنی اس کے لیے کئی باغوں کا پھل تھا — وہ اپنے ساتھی سے کہنے لگا میں تم سے مال زیادہ رکھتا ہوں اور عزت کے لحاظ سے بھی بڑھ کر ہوں۔
۳۔ عملی سبق: مال اور عزت اللہ کی عطا ہیں؛ غرور نہ کرو؛ اللہ کا شکر کرو۔"""
),
2175: (
"اور وہ اپنے باغ میں داخل ہوا ظلم کرتے ہوئے اپنی جان پر — اس نے کہا میں نہیں سمجھتا کہ یہ کبھی ختم ہو جائے گا",
"""۱۔ مالدار شخص کا غرور — باغ کبھی ختم نہ ہو گا؛ دنیا فانی ہے؛ اللہ کی قدرت۔
۲۔ ’’وَدَخَلَ جَنَّتَهُ وَهُوَ ظَالِمٌ لِّنَفْسِهِ قَالَ مَا أَظُنُّ أَن تَبِيدَ هَٰذِهِ أَبَدًا‘‘ — اور وہ اپنے باغ میں داخل ہوا ظلم کرتے ہوئے اپنی جان پر — اس نے کہا میں نہیں سمجھتا کہ یہ کبھی ختم ہو جائے گا — یعنی وہ اپنے باغ میں داخل ہوا اپنی جان پر ظلم کرتے ہوئے — اس نے کہا میں نہیں سمجھتا کہ یہ کبھی ختم ہو جائے۔
۳۔ عملی سبق: دنیا فانی ہے؛ ہمیشہ رہنے والی نہیں؛ اللہ پر بھروسہ کرو۔"""
),
2176: (
"اور میں نہیں سمجھتا کہ قیامت برپا ہو گی — اور اگر میں اپنے رب کی طرف واپس بھیجا جاؤں تو یقیناً میں اس سے بہتر جگہ پاؤں گا",
"""۱۔ مالدار شخص کی ناشکری — قیامت کا انکار؛ اللہ کی طرف لوٹنے کا یقین نہیں۔
۲۔ ’’وَمَا أَظُنُّ السَّاعَۃَ قَائِمَۃً وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيْرًا مِّنْهَا مُنقَلَبًا‘‘ — اور میں نہیں سمجھتا کہ قیامت برپا ہو گی — اور اگر میں اپنے رب کی طرف واپس بھیجا جاؤں تو یقیناً میں اس سے بہتر جگہ پاؤں گا — یعنی مجھے نہیں لگتا کہ قیامت قائم ہو گی اور اگر میں اپنے رب کی طرف واپس بھیجا گیا تو یقیناً میں اس سے بھی بہتر جگہ پاؤں گا۔
۳۔ عملی سبق: قیامت پر کامل ایمان رکھو؛ آخرت کے لیے عمل کرو؛ دنیا کی لذتوں پر بھروسہ نہ کرو۔"""
),
2177: (
"اس کے ساتھی نے اس سے گفتگو کرتے ہوئے کہا کیا تو اس کا انکار کرتا ہے جس نے تجھے مٹی سے بنایا — پھر نطفہ سے — پھر تجھے آدمی بنا دیا",
"""۱۔ ایماندار ساتھی کا جواب — مٹی سے انسان؛ پھر نطفہ؛ پھر صورت گری — یہ اللہ کا فضل ہے؛ انکار کیسا؟
۲۔ ’’قَالَ لَهُ صَاحِبُهُ وَهُوَ يُحَاوِرُهُ أَكَفَرْتَ بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَۃٍ ثُمَّ سَوَّاكَ رَجُلًا‘‘ — اس کے ساتھی نے اس سے گفتگو کرتے ہوئے کہا کیا تو اس کا انکار کرتا ہے جس نے تجھے مٹی سے بنایا — پھر نطفہ سے — پھر تجھے آدمی بنا دیا — یعنی اس کے ساتھی نے اس سے کہا کیا تو اس کا انکار کرتا ہے جس نے تجھے مٹی سے پھر نطفہ سے پھر تجھے آدمی صورت بنا دیا۔
۳۔ عملی سبق: انسان کی تخلیق اللہ کی قدرت کی نشانی ہے؛ اس پر یقین رکھو۔"""
),
2178: (
"لیکن میرا رب اللہ ہے اور میں اپنے رب کے ساتھ کسی کو شریک نہیں بناتا",
"""۱۔ مومن کا اعلان — صرف اللہ رب ہے؛ شرک سے براءت؛ خالص توحید۔
۲۔ ’’لَّٰكِنَّا هُوَ اللَّهُ رَبِّي وَلَا أُشْرِكُ بِرَبِّي أَحَدًا‘‘ —لیکن میرا رب اللہ ہے اور میں اپنے رب کے ساتھ کسی کو شریک نہیں بناتا۔
۳۔ عملی سبق: توحید اختیار کرو؛ اللہ کے سوا کسی کو رب نہ مانو۔"""
),
2179: (
"اور جب تو اپنے باغ میں داخل ہوا تھا تو تو نے یہ کیوں نہ کہا کہ ما شاء اللہ لا قوة الا باللہ — اگر تو مجھے مال اور اولاد میں کمتر دیکھتا ہے",
"""۱۔ مومن کا نصیحت — مال پر غرور کے بجائے ما شاء اللہ لا قوۃ إلا باللہ کہو؛ اللہ ہی طاقت دیتا ہے۔
۲۔ ’’وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّۃَ إِلَّا بِاللَّهِ إِن تَرَنِ أَنَا أَقَلَّ مِنكَ مَالًا وَوَلَدًا‘‘ — اور جب تو اپنے باغ میں داخل ہوا تھا تو تو نے یہ کیوں نہ کہا کہ ما شاء اللہ لا قوة الا باللہ — اگر تو مجھے مال اور اولاد میں کمتر دیکھتا ہے — یعنی جب تو نے اپنے باغ میں داخل ہوتے کوئی برکت والی بات کیوں نہ کہی کہ ما شاء اللہ لا قوۃ إلا باللہ — اگر تو مجھے مال اور اولاد میں کمتر دیکھتا ہے۔
۳۔ عملی سبق: نعمت پر ما شاء الله کہو؛ اللہ کی طاقت کے بغیر کچھ نہیں؛ تکبر سے بچو۔"""
),
2180: (
"تو امید ہے کہ میرا رب مجھے تیرے باغ سے بہتر دے گا — اور اس پر آسمان سے آفت بھیج دے گا پس وہ برابر اور پھسلن والی زمین رہ جائے گی",
"""۱۔ مومن کی دعا — اللہ اس سے بہتر دے؛ ظالم پر آسمانی آفت؛ باغ ختم ہو سکتا ہے۔
۲۔ ’’فَعَسَىٰ رَبِّي أَن يُؤْتِيَنِ خَيْرًا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِّنَ السَّمَاءِ فَتُصْبِحَ صَعِيدًا زَلَقًا‘‘ — تو امید ہے کہ میرا رب مجھے تیرے باغ سے بہتر دے گا — اور اس پر آسمان سے آفت بھیج دے گا پس وہ برابر اور پھسلن والی زمین رہ جائے گی — یعنی شاید میرا رب مجھے تیرے باغ سے بہتر باغ دے اور اس پر آسمان سے مصیبت بھیج دے پس وہ ایک پھسلن والی زمین بن جائے۔
۳۔ عملی سبق: دنیا کی دولت پر فخر نہ کرو؛ اللہ چاہے تو سب ختم کر دے؛ اللہ پر بھروسہ کرو۔"""
),
}
